-- COBIT 5 Enterprise Goals, IT-related Goals and mappings (additive and repeatable).
-- Source: COBIT 5 Framework Figure 5 (Enterprise Goals), Figure 6 (IT-related Goals),
--         Figure 17 (Enterprise Goals -> IT-related Goals), Figure 18 (IT-related Goals -> Processes/GAMO).
-- Level: P = primary, S = secondary. Matches migration 2026_11_12_000002_create_cobit5_goal_mapping_tables.

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS=0;

CREATE TABLE IF NOT EXISTS `mst_cobit5_enterprise_goals` (
    `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    `code` SMALLINT UNSIGNED NOT NULL,
    `bsc_dimension` VARCHAR(40) NOT NULL,
    `title` VARCHAR(255) NOT NULL,
    `relation_benefits_realisation` CHAR(1) NULL DEFAULT NULL,
    `relation_risk_optimisation` CHAR(1) NULL DEFAULT NULL,
    `relation_resource_optimisation` CHAR(1) NULL DEFAULT NULL,
    `order_no` SMALLINT UNSIGNED NOT NULL DEFAULT 0,
    `created_at` TIMESTAMP NULL DEFAULT NULL,
    `updated_at` TIMESTAMP NULL DEFAULT NULL,
    PRIMARY KEY (`id`),
    UNIQUE KEY `mst_cobit5_enterprise_goals_code_unique` (`code`),
    KEY `mst_cobit5_enterprise_goals_bsc_dimension_index` (`bsc_dimension`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `mst_cobit5_it_goals` (
    `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    `code` SMALLINT UNSIGNED NOT NULL,
    `bsc_dimension` VARCHAR(40) NOT NULL,
    `title` VARCHAR(255) NOT NULL,
    `order_no` SMALLINT UNSIGNED NOT NULL DEFAULT 0,
    `created_at` TIMESTAMP NULL DEFAULT NULL,
    `updated_at` TIMESTAMP NULL DEFAULT NULL,
    PRIMARY KEY (`id`),
    UNIQUE KEY `mst_cobit5_it_goals_code_unique` (`code`),
    KEY `mst_cobit5_it_goals_bsc_dimension_index` (`bsc_dimension`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `mst_cobit5_processes` (
    `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    `code` VARCHAR(10) NOT NULL,
    `domain_code` VARCHAR(5) NOT NULL,
    `domain_name` VARCHAR(60) NOT NULL,
    `title` VARCHAR(255) NOT NULL,
    `order_no` SMALLINT UNSIGNED NOT NULL DEFAULT 0,
    `created_at` TIMESTAMP NULL DEFAULT NULL,
    `updated_at` TIMESTAMP NULL DEFAULT NULL,
    PRIMARY KEY (`id`),
    UNIQUE KEY `mst_cobit5_processes_code_unique` (`code`),
    KEY `mst_cobit5_processes_domain_code_index` (`domain_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `trs_cobit5_enterprise_it_goal_maps` (
    `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    `enterprise_goal_id` BIGINT UNSIGNED NOT NULL,
    `it_goal_id` BIGINT UNSIGNED NOT NULL,
    `level` CHAR(1) NOT NULL,
    `created_at` TIMESTAMP NULL DEFAULT NULL,
    `updated_at` TIMESTAMP NULL DEFAULT NULL,
    PRIMARY KEY (`id`),
    UNIQUE KEY `trs_c5_eg_itg_unique` (`enterprise_goal_id`, `it_goal_id`),
    KEY `trs_cobit5_enterprise_it_goal_maps_it_goal_id_foreign` (`it_goal_id`),
    CONSTRAINT `trs_cobit5_enterprise_it_goal_maps_enterprise_goal_id_foreign` FOREIGN KEY (`enterprise_goal_id`) REFERENCES `mst_cobit5_enterprise_goals` (`id`) ON DELETE CASCADE,
    CONSTRAINT `trs_cobit5_enterprise_it_goal_maps_it_goal_id_foreign` FOREIGN KEY (`it_goal_id`) REFERENCES `mst_cobit5_it_goals` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `trs_cobit5_it_goal_process_maps` (
    `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    `it_goal_id` BIGINT UNSIGNED NOT NULL,
    `process_id` BIGINT UNSIGNED NOT NULL,
    `level` CHAR(1) NOT NULL,
    `created_at` TIMESTAMP NULL DEFAULT NULL,
    `updated_at` TIMESTAMP NULL DEFAULT NULL,
    PRIMARY KEY (`id`),
    UNIQUE KEY `trs_c5_itg_proc_unique` (`it_goal_id`, `process_id`),
    KEY `trs_cobit5_it_goal_process_maps_process_id_foreign` (`process_id`),
    CONSTRAINT `trs_cobit5_it_goal_process_maps_it_goal_id_foreign` FOREIGN KEY (`it_goal_id`) REFERENCES `mst_cobit5_it_goals` (`id`) ON DELETE CASCADE,
    CONSTRAINT `trs_cobit5_it_goal_process_maps_process_id_foreign` FOREIGN KEY (`process_id`) REFERENCES `mst_cobit5_processes` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- mst_cobit5_enterprise_goals (17) - Figure 5
ON DUPLICATE KEY UPDATE `bsc_dimension`=VALUES(`bsc_dimension`), `title`=VALUES(`title`), `relation_benefits_realisation`=VALUES(`relation_benefits_realisation`), `relation_risk_optimisation`=VALUES(`relation_risk_optimisation`), `relation_resource_optimisation`=VALUES(`relation_resource_optimisation`), `order_no`=VALUES(`order_no`), `updated_at`=NOW();

-- mst_cobit5_it_goals (17) - Figure 6
ON DUPLICATE KEY UPDATE `bsc_dimension`=VALUES(`bsc_dimension`), `title`=VALUES(`title`), `order_no`=VALUES(`order_no`), `updated_at`=NOW();

-- mst_cobit5_processes (37 GAMO/process) - Figure 18
ON DUPLICATE KEY UPDATE `domain_code`=VALUES(`domain_code`), `domain_name`=VALUES(`domain_name`), `title`=VALUES(`title`), `order_no`=VALUES(`order_no`), `updated_at`=NOW();

-- trs_cobit5_enterprise_it_goal_maps (141 links) - Figure 17
ON DUPLICATE KEY UPDATE `level`=VALUES(`level`), `updated_at`=NOW();

-- trs_cobit5_it_goal_process_maps (416 links) - Figure 18
ON DUPLICATE KEY UPDATE `level`=VALUES(`level`), `updated_at`=NOW();

SET FOREIGN_KEY_CHECKS=1;

-- Register migration so 'php artisan migrate' does not recreate the tables
SELECT '2026_11_12_000002_create_cobit5_goal_mapping_tables', 99 FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM `migrations` WHERE `migration` = '2026_11_12_000002_create_cobit5_goal_mapping_tables');
